return {["Sheet1"]={["10000"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10000,["open"]=1,["text"]=[[据宫中线人来报，兵部尚书明大人已上奏陛下，请求朝廷向各地商行收购大量兵器、伤药囤积。走到这步，呵呵，看来是前线战事吃紧呐！]],["title"]=[[宫中流言]],["type"]=1,["type2"]=1},["10001"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10001,["open"]=1,["text"]=[[据一位户部侍郎的妾室所言，近日里户部已安排官吏，下乡前往各地村庄小镇，以较为低廉的价格从当地农家的手中购入大量口粮。不知是户部的未雨绸缪，还是上面有人刻意安排，真是耐人寻味啊！]],["title"]=[[户部囤粮]],["type"]=1,["type2"]=1},["10002"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10002,["open"]=1,["text"]=[[近日里宫中发生了一件大事。诸位王爷与吏、户、礼、兵各部在朝堂上联名上奏，请求陛下务必安排人手，搜集采购民间各类物资、宝物，扩充国库。看这架势，不久后朝廷便会设置官员，下到民间各地搜集物资，进行国库的扩充。]],["title"]=[[国库扩充]],["type"]=1,["type2"]=1},["10003"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10003,["open"]=1,["text"]=[[前日礼部的一位故友找到我，拜托我帮他搜罗中原的奇珍异宝，说是礼部接到任命，不久后将要派人与异国官员进行秘密谈判。哈哈，多带几件宝物，手上也就多几分筹码。]],["title"]=[[异国谈判]],["type"]=1,["type2"]=1},["10004"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10004,["open"]=1,["text"]=[[边关来报，山海关战事有变。据山海关镇守使张治诚将军所言，众将士倚关而守，无论是巡访还是调度都安排得密不透风，哪怕是一只鸟都飞不进来。但前日夜里，关内兵械库、粮仓均被人纵火焚烧。守卫赶到时，瞥见那纵火之人的身影，再去追捕时那人却已消失得无影无踪。最后粮仓损失惨重，兵械库却因守卫及时抢救，得以保存。]],["title"]=[[前线动荡壹]],["type"]=1,["type2"]=1},["10005"]={["arg1"]=10004,["arg2"]=0,["arg3"]=0,["con1"]=4,["con2"]=0,["con3"]=0,["id"]=10005,["open"]=1,["text"]=[[山海关经粮仓纵火一事后，镇守使张将军搜查纵火之人的下落，却是音信全无。怀疑军中有内鬼，连夜彻查后察明全军未有二心之人。此事令张将军百思不得其解，那纵火之人竟好似凭空消失一般。嘿嘿，这天底下有如此神通之人，只有东瀛风魔里的忍武者了。]],["title"]=[[前线动荡贰]],["type"]=1,["type2"]=1},["10006"]={["arg1"]=10005,["arg2"]=0,["arg3"]=0,["con1"]=4,["con2"]=0,["con3"]=0,["id"]=10006,["open"]=1,["text"]=[[据我朝中一位故友密报所言，陆千侯爷已调度手下无名、飞鹰二位神捕前往山海关支援。哼！圣人无名，神眼飞鹰，这两句话可不是空口无凭。等二位神捕到了山海关，那风魔里忍武者再想做点什么，怕是难比登天了。可叹，前线竟到了要这两位出手支援的地步，看来我们老百姓往后的日子怕是不太好过咯！]],["title"]=[[前线动荡叁]],["type"]=1,["type2"]=1},["10007"]={["arg1"]=10006,["arg2"]=0,["arg3"]=0,["con1"]=4,["con2"]=0,["con3"]=0,["id"]=10007,["open"]=1,["text"]=[[这段时间关外外族动作频频，据说多方势力已经形成联盟，其中包括：东瀛、高丽、罗刹、暹罗等等。而这支外族联盟军里，也汇集了不少来自各方各地的能人异士。此事非同小可，无论是边关众将还是朝野上下，皆不敢掉以轻心，以防局势有变。]],["title"]=[[前线动荡肆]],["type"]=1,["type2"]=1},["10008"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10008,["open"]=1,["text"]=[[入关做生意的外族人越来越多，有些边关小镇几乎成为他们的地盘，最近朝廷下令要对这些人的身份进行严查，一夜之间黑市里贩卖的入关通行证重金难求，这要说里面没猫腻，傻子都不信。]],["title"]=[[严查异族入关壹]],["type"]=1,["type2"]=1},["10009"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10009,["open"]=1,["text"]=[[这些时日边关的外族人数离奇增多，有些商人身上一股煞气，瞧着就不简单，这不，朝廷颁发了政策，对边关开始严格管控，外族人必得随身携带身份文书，不然过不了审查，会被直接抓进大牢，可怕的很呐]],["title"]=[[严查异族入关贰]],["type"]=1,["type2"]=1},["10010"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10010,["open"]=1,["text"]=[[这些日子刑场上的血不曾干枯过，掉脑袋的都是些没有拿出身份证明的外族人士，这些人就像不怕死一样，杀光一波又混进城一波，啧，我在边关长这么大，头一回瞧见这种场面。]],["title"]=[[严查异族细作壹]],["type"]=1,["type2"]=1},["10011"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10011,["open"]=1,["text"]=[[自朝廷下令严查入关外族人士身份，城内酒馆的生意便差了许多，官兵一日上门查三趟，闹得客人们提心吊胆，不过百姓虽有些怨言，但也十分配合，毕竟朝廷此举是为维护治安，要我说，这城里的外族人士确实太多了，鱼目混杂的，让人心慌。]],["title"]=[[严查异族细作贰]],["type"]=1,["type2"]=1},["10012"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10012,["open"]=1,["text"]=[[朝廷这段时日里命官兵上街巡逻，走访居民严查可疑人士，我一好友从南方来这做买卖，因当时无熟人引路，险些被官兵当成细作打杀。现在街上别说流氓痞子，连乞丐都少见咯，也不知朝廷闹这么大阵仗所为何事。]],["title"]=[[治安管理壹]],["type"]=1,["type2"]=1},["10013"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10013,["open"]=1,["text"]=[[我有个表兄在官府里当差，他透露几句消息给我，现在不止大城里要官兵每日巡逻走访，连下面村庄小镇都不能落下，如今官府里人手紧缺，要新招不少人，我本想趁机跟我表兄混口饭吃，结果他把我臭骂一顿，说什么形势复杂，这差事会丢命，依此看朝廷是要有大动作啊。]],["title"]=[[治安管理贰]],["type"]=1,["type2"]=1},["10014"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10014,["open"]=1,["text"]=[[风雨欲来，天下将乱，时隔数年有“定海平渊”威名之称的武林盟重出江湖，由诸多门派势力联合把持，将代表武林最高决策主体。]],["title"]=[[武林盟重出江湖]],["type"]=1,["type2"]=1},["10015"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10015,["open"]=1,["text"]=[[身为武林中人，在国家有危、百姓受难之际，无论正派还是邪派，都应该先放下成见，齐心协力，联手抵御外敌入侵。]],["title"]=[[号召武林团结]],["type"]=1,["type2"]=1},["10016"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10016,["open"]=1,["text"]=[[镇山守河，寸土不让，不负先辈之志，侠之大者，为国为民！]],["title"]=[[碧血丹心照河山]],["type"]=1,["type2"]=1},["10017"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10017,["open"]=1,["text"]=[[诸位侠士只要按武林盟的规矩办事，不管身份是能见光还是不能见光，嘿嘿，武林盟皆一视同仁，从不问正邪。]],["title"]=[[武林盟立场]],["type"]=1,["type2"]=1},["10018"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10018,["open"]=1,["text"]=[[江山飘摇，社稷动荡。据可靠情报，那曾经号令江湖群英，如今消失已久的武林盟会即将重出江湖。曾经，武林盟会一出，一众江湖门派，无论正邪与否，无论大小强弱，皆要派出门中长老弟子参加，选出武林盟主。江湖豪侠听从盟主发号施令，中原武林上下团结一心，共渡难关。而今重现武林盟会，唉，中原武林危矣。]],["title"]=[[中原危，武林盟出]],["type"]=1,["type2"]=1},["10019"]={["arg1"]=10018,["arg2"]=0,["arg3"]=0,["con1"]=4,["con2"]=0,["con3"]=0,["id"]=10019,["open"]=1,["text"]=[[数十年前，上届武林盟会之时，天下群侠逐鹿，各自抽签与对手在擂台上切磋大比，只为争得武林盟主的宝座。最终，由崆峒派莫血衣与龙城山庄慕容兴决战，二人胜者即是新任武林盟主。谁知崆峒逆劲拳与燕氏磁南指难分胜负，一人出招先伤己后伤人，另一人以彼之道还施彼身，这结果只能是两败俱伤。最后二人无力再战，胜负不分。选不出武林盟主，故后来这武林盟会也就不了了之了。]],["title"]=[[武林盟选盟主之事]],["type"]=1,["type2"]=1},["10020"]={["arg1"]=10019,["arg2"]=0,["arg3"]=0,["con1"]=4,["con2"]=0,["con3"]=0,["id"]=10020,["open"]=1,["text"]=[[据小道消息所言，这次的武林盟会发起人，正是德高望重的少林圆悲大师。圆悲大师慈悲为怀，无论是正派还是邪派，听到圆悲大师的法号，无人不肃然起敬。可惜圆悲大师一心向禅，少问世事，如若不然，江湖群侠定然会把圆悲大师，推举上这武林盟主的位子。]],["title"]=[[武林盟发起人]],["type"]=1,["type2"]=1},["10021"]={["arg1"]=10020,["arg2"]=0,["arg3"]=0,["con1"]=4,["con2"]=0,["con3"]=0,["id"]=10021,["open"]=1,["text"]=[[以小生的粗浅眼光来看，在这么多武林盟主的候选人中，单论武功实力，峨眉宝相神尼应当首屈一指。小生有幸，曾在有生之年见识过宝相神尼的惊天一剑，可谓旷古烁今，放眼江湖无人能出其右。若是宝相神尼神剑下山，势要争一争这武林盟主的位子，哈哈，那我们就可以看好戏了！]],["title"]=[[峨眉宝相神尼之威]],["type"]=1,["type2"]=1},["10022"]={["arg1"]=10021,["arg2"]=0,["arg3"]=0,["con1"]=4,["con2"]=0,["con3"]=0,["id"]=10022,["open"]=1,["text"]=[[江湖传言，许多正派有识之士都想请武当山张松溪前辈继任这武林盟主的位子。若论武功造诣，张松溪比不上宝相神尼，若论人心所向，张松溪更比不上圆悲大师，但如果单要论智略和管理，我想，张松溪才是这最佳的人选。别的不说，光是这些年武当山为我们中原武林做出的贡献，就远非其他门派可比。中原武林一度没有武林盟会，而未曾分崩离析，张松溪前辈可谓功不可没。]],["title"]=[[武林盟盟主位猜测]],["type"]=1,["type2"]=1},["10023"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10023,["open"]=1,["text"]=[[近来天都峰上有三奇，奇景奇人奇棋局，奇人辟谷入棋局，久观棋者入奇境。若是闲来无事，倒也可上天都峰看看奇景，找找奇人，观观棋局，说不定会有什么千载难逢的际遇。]],["title"]=[[天都三奇]],["type"]=1,["type2"]=1},["10024"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10024,["open"]=1,["text"]=[[少侠可信在梦中能提升武学？这事虽听着不真切，但是确有其事。近来有侠士说自己常常做梦，而他多年未能突破的武学瓶颈竟在梦中得以突破。在下就不指望能得如此奇遇了，但少侠福泽深厚，若是能有此奇遇倒也不稀奇。]],["title"]=[[梦中奇遇]],["type"]=1,["type2"]=1},["10025"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10025,["open"]=1,["text"]=[[古有庄周梦蝶，似真似幻，今有侠士入奇梦，难分真假。有侠士说自己做了一个离奇的梦境，在梦境中体验了一番与众不同的战斗，醒来时仍双拳紧握，热血未凉，一时间分不清梦里梦外。]],["title"]=[[意犹未尽的战斗]],["type"]=1,["type2"]=1},["10026"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10026,["open"]=0,["text"]=[[白牡丹与百花杀在天都峰相约斗戏，决意要在此分出谁才是天下第一的花旦，这可是切切实实的一出好戏，少侠万万不可错过。]],["title"]=[[天都斗戏]],["type"]=1,["type2"]=1},["10027"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10027,["open"]=0,["text"]=[[百花杀和白牡丹都是闻名天下的花旦，传说她们在表演时，会佩戴一种可以千变万化的戏曲面具。若是少侠有此兴致，也可以上天都峰观摩一番。]],["title"]=[[戏痴面具]],["type"]=1,["type2"]=1},["10028"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10028,["open"]=0,["text"]=[[两位名伶花旦在天都斗戏，引得天下爱戏之人皆前往一观，其中更有不少绘制戏曲面具的大师，带上工具和各色颜料，只为在斗戏之时，能多多宣传自家生意。]],["title"]=[[面具大师]],["type"]=1,["type2"]=1},["10029"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10029,["open"]=1,["text"]=[[新入江湖的少侠面对偌大的江湖常常会觉茫然无措，一位江湖前辈见此情景也思及当初自己的不易，于是便将自己经验总结写入笔录之中，传给一些初入江湖的年轻人，望能给其带来一些指引。]],["title"]=[[江湖笔录]],["type"]=1,["type2"]=1},["10030"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10030,["open"]=1,["text"]=[[武林盟有间厢房，有些曾入住其中的武林先贤，会将自己所学所思所悟抄录下来存于书案，望能给未来入住其中的中原武林弟子，传承绝技、指点迷津，以此为武林多添栋梁。那些先贤有如此胸怀，着实可敬。]],["title"]=[[武林先贤]],["type"]=1,["type2"]=1},["10031"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10031,["open"]=1,["text"]=[[据说，风、云二位老板，特意为一些出色的武林盟弟子准备了一间厢房，方便这些中原子弟在天都峰休息。听闻这间厢房内，设有一座书案，其上记载了某些武林先贤留下的感悟。不知是哪位侠士能如此幸运分得此房。]],["title"]=[[武林盟厢房]],["type"]=1,["type2"]=1},["10032"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10032,["open"]=0,["text"]=[[少侠若是得到一本江湖前辈的笔录，不如按其上所述修炼一番，这是前辈游历江湖时总结的经验，或许能从中得到一些意外收获。]],["title"]=[[前辈的指引]],["type"]=1,["type2"]=1},["10033"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10033,["open"]=0,["text"]=[[武林大会举办期间，出现一批擅长制器的奇人异士，联手将诸位侠客的锻炼炉大加改进，可铸造的神兵数量随之提升。]],["title"]=[[锻造炉改进]],["type"]=1,["type2"]=1},["10034"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10034,["open"]=1,["text"]=[[最近有一折戏曲在下听来颇觉有趣，那戏中唱的是某位叶家小姐，说她幼时丧母，不得父亲所喜，遭父亲宠妾虐待，幸遇高人收之为徒。这高人乃当世武学奇才，教出的徒弟亦是不差，短短几年，叶家小姐便成武功高手，痛快地向叶家报仇雪耻。]],["title"]=[[叶家小姐]],["type"]=1,["type2"]=1},["10035"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10035,["open"]=0,["text"]=[[听说现在集市上卖的风筝对比以前能飞得更高更稳，以后大家放风筝会容易很多呢。]],["title"]=[[风筝攀云]],["type"]=1,["type2"]=1},["10036"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10036,["open"]=0,["text"]=[[红松阁的阁主常听少侠们抱怨书箱开关不甚灵活，于是特意命工匠将诸位的书箱修整了一番，以解诸位的烦愁。]],["title"]=[[侠客书箱]],["type"]=1,["type2"]=1},["10037"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10037,["open"]=1,["text"]=[[有人花钱在外地买了处宅子，重新翻修时竟从院中挖出数十具尸骨，于是上报官府。经一番调查得知，这宅子原来的主人是位姓叶的富商，多年前某一雨夜，叶老爷的宠妾中邪发狂，将全府上下老小悉数屠杀，等几日后左右邻居察觉到叶府异样时，那宠妾已不知去向。而大伙清点完尸体，发现唯独少了叶家小姐，又听附近老人所述，那宠妾素来对先夫人的独女非打即骂，叶小姐定然凶多吉少，惨的是小小年纪竟连尸骨也无。曾有酒鬼说那晚亲眼看见叶家小姐和陌生男子一起跃过城墙离开，身后还跟着一浑身是血、对他们俯首服从的女人，当然酒鬼的话自是无人相信的。]],["title"]=[[叶家凶宅]],["type"]=1,["type2"]=1},["10038"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10038,["open"]=1,["text"]=[[近日在下听闻，天都峰上有武林盟弟子连发噩梦，梦见数十年前的一桩惨案。梦中场景可谓惨绝人寰，让那名弟子夜夜担惊受怕，失眠了多日。]],["title"]=[[恐怖噩梦]],["type"]=1,["type2"]=1},["10039"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10039,["open"]=1,["text"]=[[听闻多年前在南疆有位横空出世的武学奇才，他年幼时身患恶疾，昏迷七日，醒来后全身病痛不仅不药而愈，还自称在鬼门关遇到阴阳二使，二使传其武功后，将其送回阳间。数年后，他竟自创多门神功武学，成为南疆一域闻名的一代宗师。]],["title"]=[[武学奇才]],["type"]=1,["type2"]=1},["10040"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10040,["open"]=1,["text"]=[[近日有江湖弟子发现，频繁观摩棋局后会出现某些后遗症。为此，江湖中诸多高手对此事展开调查。据传，调查无果，众高手也暂无头绪，为避免未知的危害，众高手准备对棋局的观摩进行限制。]],["title"]=[[梦中棋局]],["type"]=1,["type2"]=1},["10041"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10041,["open"]=1,["text"]=[[据传，有人特意开办了管家私塾，其中的学生自然是各个府邸的管家，此私塾之中有先生传授更为高级的执家之法，听闻很多达官贵人府中的管家都已经前往学习。]],["title"]=[[管家的修养]],["type"]=1,["type2"]=1},["10042"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10042,["open"]=1,["text"]=[[据坊间传言，边境处出现一个以传授女子手艺活为主的艺堂，听说从中出来的女子各个心灵手巧。闻听此信，绣娘便招揽了一众姐妹，相约一同前往。]],["title"]=[[心灵手巧]],["type"]=1,["type2"]=1},["10043"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10043,["open"]=1,["text"]=[[听某个府上的老爷说，他们府上的管家自从去了管家私塾研习回来后，整个人的办事效率大大提高，现在府中一切事务都由管家全权负责，一切井然有序。]],["title"]=[[高级管家]],["type"]=1,["type2"]=1},["10044"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10044,["open"]=1,["text"]=[[绣娘的好友阿红以前只会将一些面具拆解成简单的材料，自从她前往艺堂学习回来后，阿红竟然能将更为贵重的挂饰拆解成完整的材料。阿红的成长让绣娘不禁感叹，询问后绣娘决定一定要去艺堂进修一番。]],["title"]=[[妙手生花]],["type"]=1,["type2"]=1},["10045"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10045,["open"]=1,["text"]=[[忽有江湖传闻称，一神秘老者偶然获得一种可以加快功法修炼的秘宝，还说获此宝物可将修炼功法的效率大幅提高，事半功倍。对于此传言，江湖中人的看法却参差不齐，有人说这老头一定是某个失传门派的高人，还有人说，这老头就是一个江湖骗子，武学练成怎么可能有此般捷径可言。至于传闻是真是假，便不得而知。]],["title"]=[[天材地宝]],["type"]=1,["type2"]=1},["10046"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10046,["open"]=1,["text"]=[[近日，天都峰的先贤书案处聚集了很多江湖中颇有名望的前辈，他们对先贤书案中江湖弟子留下的感悟进行了梳理。前辈们看到如此多的武学感悟甚是欣慰，为此，众前辈也鼓励号召所有武林中人，除了武学的感悟外，还可将对招式的感悟一同记录其中。]],["title"]=[[功法传承]],["type"]=1,["type2"]=1},["10047"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10047,["open"]=1,["text"]=[[某日，天竞门长老在整理先师遗物时偶然发现一幅地图，此事上报给杨秋白后又经过三天三夜的研讨，最终由杨秋白亲自带门内高手前往地图上的标注所在。当推开地下石门，众人发现石室中堆着几个落满灰尘的箱子，箱中竟然是些天竞门已经失传的武学。]],["title"]=[[天竞门密藏]],["type"]=1,["type2"]=1},["10048"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10048,["open"]=1,["text"]=[[近日，江湖中突然流传出一种新的练功方式，据传是一位白发老者的毕生所创。起初，江湖中人对此方式不予接受，直到众门派派出高手证实，这方式的确比以往所用的方式更为高效。据白发老者所说，这方式只是在原来练功方式的基础上取长补短，精益求精，核心要领还是不变的。自此，这种新的练功方式逐渐被江湖中人接纳学习。]],["title"]=[[精益求精]],["type"]=1,["type2"]=1},["10049"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10049,["open"]=1,["text"]=[[据传，不久前有名海鲸弟子夜巡时不慎踩塌古船腐朽的木板落入深处，将那名失足的弟子救起之后，得知古船的深处另有乾坤。仇慕仲知晓后当即率领弟子前往古船深处，一番探寻下在一处破败的房间内发现一具尸骸，而尸骸怀中怀抱着一个木箱。木箱早已腐朽，箱中之物大多破败蒙灰，但有两本古籍竟还完好无缺。
仇穆仲深研古籍内容，发现撰写之人乃是海鲸帮一名外出云游的长老，而这两本古籍记载的便是长老的毕生所学，由游鲛所悟出的刀法与轻功。与堂主们商量之后，仇穆仲决定将这两本秘籍授予有较高贡献的弟子，使其得以传承。]],["title"]=[[古船乾坤]],["type"]=1,["type2"]=1},["10050"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10050,["open"]=1,["text"]=[[据传那落月庄主萧逸龙做了一个奇梦，梦中有一颗参天古树，古树旁有一位须发银白的老者，在月下独酌。而后有仙音妙韵，随风缥缈，似从月中来。酌酒之人半醉朦胧，随音而舞剑，月辉潺潺与剑光相映，一招一式超逸绝伦。
老者的剑法萧逸龙从未见过，但却觉得无比熟悉。正当萧逸龙沉思之时，老者剑锋一转，挥出数道剑芒，瞬息间周边树木巨石皆断。而其中一道剑芒直逼萧逸龙所在，心惊之时萧逸龙已然梦醒，冷汗涔涔。
多日后，萧逸龙外出，途径一处宝地，宝地有一颗参天古树，月下之景竟与梦中如出一辙。于是萧逸龙在古树边探查，最终在一个隐秘的树洞中发现两本古籍。萧逸龙回到落月山庄后，深研两本古籍，发现古籍乃是落月前辈所著，记载着失传的剑法和轻功，思索之下决定将两门绝学授予门内有较高贡献的弟子。]],["title"]=[[梦引月华]],["type"]=1,["type2"]=1},["10051"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10051,["open"]=1,["text"]=[[自各大宅府中的管家前往进修开始，逐渐有些学有所成之人归来，他们回到府邸后所表现出的能力让人吃惊。相较以前而言，进修后他们处理事务种类更多，效率更高，这一成长着实是叫各位家主赞不绝口。因此近乎所有管家都在家主的支持下前往进修，只待学有所成之日能为家主分忧。]],["title"]=[[家政有方]],["type"]=1,["type2"]=1},["10052"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10052,["open"]=1,["text"]=[[据坊间流传，四柳并非只有四位柳姑娘，实则是有五位。据说那第五位柳姑娘是天下客栈的人，向来深居简出，少有人见。但坊间传言向来半真半假，也曾有不少人找四柳的四位柳姑娘询问，但得到的答案却各不相同。]],["title"]=[[四柳]],["type"]=1,["type2"]=1},["10053"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10053,["open"]=1,["text"]=[[近日很多江湖中人传言说经常能看见燕氏皇族中的“小霸王”慕容米频繁出入昆仑、蜀中唐门、明月楼、天狼教与落月山庄等地。有人说慕容米此番拜访很可能是得到了什么与这些门派相关的重要消息，也有人说慕容米就是闲来无事乱逛，对于慕容米的行踪目的江湖中猜测众多，一时间也不知谁说的是对的。]],["title"]=[[少女迷踪]],["type"]=1,["type2"]=1},["10054"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10054,["open"]=1,["text"]=[[多年前，有杏林世家，望闻问切，开方抓药，皆是一绝。可惜飞来横祸，一场变故叫那杏林世家转眼便在江湖上销声匿迹，祖传的药方典籍随着那杏林世家一齐消失。
近日，江湖上忽然出现了一老者，声称自己得到了那杏林世家传承，研制出了一种可以使人精神迅速恢复的神药。传闻一出，就连一些杏林圣手都被之惊动，欲寻那老者探讨。老者也不避讳，直道是自己寻得了药典的残页，但残页在他记下后便已烧毁。
而老者所售的神药，确也如他所说，功效极佳。老者还将药分稍作改动，将神药分为四档品质，价格也随之不同，一时间求药之人踏破门槛。也有财大气粗之人掷以重金，望老者将药方相授，但皆被拒绝。]],["title"]=[[杏林世家]],["type"]=1,["type2"]=1},["10055"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10055,["open"]=1,["text"]=[[早年间，各大府邸聘请家仆未有一套较为完善的规制，使得有一位家主拖欠家仆薪资三年之久，其数额大得惊人。近日红松阁将此规制拟定完善，现今无论何种原因，拖欠家仆薪资的日期最长为三十日，超出七日的金额由红松阁代付。此消息一出，众多家主纷纷叫好。]],["title"]=[[欠薪补助]],["type"]=1,["type2"]=1},["10056"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=10056,["open"]=1,["text"]=[[据说，有个天狼教的小弟子误入了一个地窟，还从中带出了两本古籍，而后便将古籍上交给了魏师道，得了不少奖赏。一些有幸翻看过古籍的弟子都说，古籍是用某种暗语撰写，不是他们所知的任何一种文字。魏师道拿到古籍后便闭关专研，过了小半月才破解了暗语。据说那两本古籍乃是天狼祖师爷撰写，一本是暗器绝学，一本是轻功绝学。而魏师道出关后便告知众人，他要将这两本绝学授予对门派贡献颇高的弟子，这在天狼教内引起了不小的震动。]],["title"]=[[天狼迷书]],["type"]=1,["type2"]=1},["20000"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20000,["open"]=1,["text"]=[[传闻关于周天功的四件宝物，铁盒、水晶和玉筷已现江湖，唯独金牌毫无线索，有流言说被崆峒派掌门的莫血衣所得，不知此消息是真是假。]],["title"]=[[周天功四大宝物]],["type"]=2,["type2"]=1},["20001"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20001,["open"]=1,["text"]=[[万兽门的弟子首席云潇湘，上个月广发江湖告示，愿花重金为他饲养的白狼求配偶，虽说银两数目惹人眼红，但有些侠士也不至于自卖自身，云潇湘是给狼找配偶，不是给他本人啊！]],["title"]=[[云潇湘重金求狼种]],["type"]=2,["type2"]=1},["20002"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20002,["open"]=1,["text"]=[[丐帮帮主施楠下落不明，由江上游暂代帮主之位，帮内有人对此不服，江上游便和这些人比试了三天两夜，以一敌众，场上无人能撼动其锋芒，这场比试彻底让他坐稳代帮主之位。]],["title"]=[[江上游技压群雄]],["type"]=2,["type2"]=1},["20003"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20003,["open"]=1,["text"]=[[不知哪个缺德的散布假消息，宣扬万灵谷的毒酒可以青春永驻，劝告各位女侠士千万别尝试，逍遥林的神医薛慕华已经将解药涨价到三千两，买不起就只能等死了。]],["title"]=[[万灵谷毒酒谣言误]],["type"]=2,["type2"]=1},["20004"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20004,["open"]=1,["text"]=[[江湖上流言崆峒派的王绝与柳玄风关系匪浅，不过王绝有“落日神拳”的称号，目前没人敢去找他求证。]],["title"]=[[崆峒派王绝陷流言]],["type"]=2,["type2"]=1},["20005"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20005,["open"]=1,["text"]=[[行走江湖怎么能没有一把趁手的武器，欧冶子大师愿教有缘之人学铸造，诸位若想知道自己是不是那位有缘人，可找李铁嘴算上一卦，不用九百九，只需九两八，绝对童叟无欺。]],["title"]=[[李铁嘴卦算有缘人]],["type"]=2,["type2"]=1},["20006"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20006,["open"]=1,["text"]=[[官府的凌云为捉拿大盗草上飞，在苏州设下天罗地网，怎料草上飞还是顺利逃脱，现在整个江湖的盗贼都在猜测草上飞是用了什么手段。]],["title"]=[[大盗草上飞胜凌云]],["type"]=2,["type2"]=1},["20007"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20007,["open"]=1,["text"]=[[多年前，临淄盗墓夏侯家出了一位名震一时的天才，此人无论是堪舆之术还是机关之术，在当时可谓技压群雄。但不知该说他是艺高人胆大，亦或是年少轻狂，竟接下了胡家人的委托，盗取了方濯君墓中的《周天功》。匹夫无罪，怀璧其罪。后夏侯家被人无穷无尽地追杀，而他也被迫逃进一座古墓之中，将这段往事埋葬于此。]],["title"]=[[周天功竟出自古墓]],["type"]=2,["type2"]=1},["20008"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20008,["open"]=1,["text"]=[[这段时间，中原武林风波四起，江湖上传出一个神秘的组织，能把门中弟子变得如傀儡木偶、行尸走肉一般，无法正常思考行动，只会乖乖听控制者摆布。]],["title"]=[[神秘组织修炼诡术]],["type"]=2,["type2"]=1},["20009"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20009,["open"]=1,["text"]=[[听闻近日金牛武馆又在招木房管事和水房管事，这两个真是高危职业，少侠若要去金牛武馆做工，可得避着点。]],["title"]=[[金牛武馆招工]],["type"]=2,["type2"]=1},["20010"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20010,["open"]=1,["text"]=[[听闻昨日金牛武馆的厨子去报官了，因为他放在饭厅的馒头经常莫名失踪。不过这厨子蒸馒头的手艺属实一绝，少侠可有尝过？]],["title"]=[[馒头失踪案]],["type"]=2,["type2"]=1},["20011"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20011,["open"]=1,["text"]=[[听闻秋月被沉尸于池塘中，可怜她一生忠心，未曾想会葬身在被她视若亲母的朱夫人手里，可悲可叹呀。]],["title"]=[[秋月之死]],["type"]=2,["type2"]=1},["20012"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20012,["open"]=1,["text"]=[[听闻昨日衡阳刘府的小姐，刘老爷之女，刘秀娘又趁着他爹不注意偷跑出门了，刘府已派人寻找，目前未有结果，但刘老爷并未动怒似乎已经习惯了。]],["title"]=[[刘府的寻人告示]],["type"]=2,["type2"]=1},["20013"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20013,["open"]=1,["text"]=[[传闻说杨柏秋和赛娇娇当年也是门派新秀，在江湖中小有名气，因为师门相对而一齐叛离师门，私奔到恶人村开了两家黑店。有不少人着了他们的套，听闻少侠也是其中之一，哈哈哈，少侠下次再去可得当心点。]],["title"]=[[开黑店的亡命鸳鸯]],["type"]=2,["type2"]=1},["20014"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20014,["open"]=1,["text"]=[[传闻田小芳幼时流浪街头，曾在大户人家做过丫环，因手脚不干净而被发卖。赛娇娇看她幼时凄苦与自己相似，且店里正好缺人手便将她赎回来做丫环。不过田小芳并不满足于做个丫环，她似乎更想加入那个家。]],["title"]=[[田小芳往事]],["type"]=2,["type2"]=1},["20015"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20015,["open"]=1,["text"]=[[听闻昨日杨柏秋又从黑商那里拿了一批古董赝品，不知下一个中招的倒霉蛋是谁。]],["title"]=[[杨柏秋]],["type"]=2,["type2"]=1},["20016"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20016,["open"]=1,["text"]=[[赛娇娇开的虽然是黑店，但是她的招牌菜“青龙闹海”着实一绝，不过品尝的前提是要付得起钱或是能打得过她。]],["title"]=[[黑店名菜]],["type"]=2,["type2"]=1},["20017"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20017,["open"]=1,["text"]=[[昨日听闻恶人村的药神和他的妻子起了争执，神医的脸上多了一个巴掌印，据说他们争执的起因是一本书，也不知何书能有如此威力，少侠可知那是何书？]],["title"]=[[神奇的书]],["type"]=2,["type2"]=1},["20018"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20018,["open"]=1,["text"]=[[据说那恶人村的戴不恭好赌博，为还赌债竟将妻子媚儿发卖，好在媚儿得少侠相助逃出。在下听闻媚儿回家后将戴不恭骂的狗血淋头后扫地出门，还找了人将他痛揍一顿，实在是大快人心啊。]],["title"]=[[好赌成性戴不恭]],["type"]=2,["type2"]=1},["20019"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20019,["open"]=1,["text"]=[[胡家寨也曾是荆州一霸，名动江湖，当初为寻一宝，遭人陷害，一朝衰落。如今又因那一宝物，一夕之间，满门倾灭，着实令人唏嘘。胡蒙为让家族重回巅峰四处寻宝，为获此宝而付出惨重代价，如此当真值得么？]],["title"]=[[风雨飘摇胡家寨]],["type"]=2,["type2"]=1},["20020"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20020,["open"]=1,["text"]=[[张灵儿深得父亲宠爱，天真单纯、不谙世事，没想到竟然被刘方所骗做出这般坑爹之举，还好醒悟及时。传闻张灵儿回去后性情大变，与父亲学起了商贾之术，张老爷子也很是开明，不在乎张灵儿的女子身份对她倾囊相授，这也算是因祸得福吧。]],["title"]=[[张灵儿性情大变]],["type"]=2,["type2"]=1},["20021"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20021,["open"]=1,["text"]=[[华山村南村口的老大娘又新买了小鸡仔，不知这几只能否逃离被流氓地痞偷了吃的命运。]],["title"]=[[老大娘的下蛋鸡]],["type"]=2,["type2"]=1},["20022"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20022,["open"]=1,["text"]=[[心斋御虚功在华山村的山洞中现世，引得众多江湖中人前来一探，华山村的村民们因此卖出了不少特产。]],["title"]=[[华山村特产]],["type"]=2,["type2"]=1},["20023"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20023,["open"]=1,["text"]=[[据传那逍遥林的打铁屋是与杨柏秋的酒馆有得一拼的黑店，不过那打铁匠更喜欢精准打劫。有人说他以宝剑蛊雕作饵，开出高价向人推荐，一旦确定购买，打铁匠便会出手劫杀。那宝剑蛊雕就是一道门槛，打铁匠就以此提高打劫的成功率。]],["title"]=[[精准打劫的铁匠]],["type"]=2,["type2"]=1},["20024"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20024,["open"]=1,["text"]=[[传闻柳玄风曾也是嫉恶如仇，希望成为惩恶扬善的大侠，只可惜造化弄人，他脚下的路也渐渐的偏离了他最初所期望的。]],["title"]=[[世事不遂愿]],["type"]=2,["type2"]=1},["20025"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20025,["open"]=1,["text"]=[[沈元龙身为一帮掌管酒楼的行首，竟老在何园弄丢礼盒，在下怀疑他是以此结交少侠这样的新秀，为帮派招人。]],["title"]=[[不小心的沈元龙]],["type"]=2,["type2"]=1},["20026"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20026,["open"]=1,["text"]=[[红绳结姻缘，少侠送予小红娘一条红绳，说不定可以让小红娘为少侠结个姻缘。不过依少侠如此英明神武之姿，大概率是找不到能与少侠相匹之人。]],["title"]=[[红绳结姻]],["type"]=2,["type2"]=1},["20027"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20027,["open"]=1,["text"]=[[方剑锋勾结商号老板樊子发欺压乡里，据说现已被本派处罚，多亏了少侠仗义出手，揭露了这小子的罪行。]],["title"]=[[惩治方剑锋]],["type"]=2,["type2"]=1},["20028"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20028,["open"]=1,["text"]=[[听闻玄定小师傅又被罚抄经书了，他一时偷懒托人帮他送手抄经书给智净师傅的时候，估计没想到会给他带来双倍的罚抄，这大概便是因果吧。]],["title"]=[[偷懒的后果]],["type"]=2,["type2"]=1},["20029"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20029,["open"]=1,["text"]=[[迦那罗自天竺至东土求禅，入了空门却未能断了情根，拼得一命只为渡一人。]],["title"]=[[尘缘往事壹]],["type"]=2,["type2"]=1},["20030"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20030,["open"]=1,["text"]=[[秦采薇与幽冥教主，一是天真少女，一是众人口中的邪教教主。秦采薇心善，救起重伤的幽冥教主，却误将芳心暗许。两人本应缘尽于幽冥教主的不辞之别，却因迦那罗的不忍而铸成孽缘，迦那罗最终也食下了自己的果。]],["title"]=[[尘缘往事贰]],["type"]=2,["type2"]=1},["20031"]={["arg1"]=[[20029,20030]],["arg2"]=0,["arg3"]=0,["con1"]=4,["con2"]=0,["con3"]=0,["id"]=20031,["open"]=1,["text"]=[[只叹是有因有缘集世间，有因有缘世间集；有因有缘灭世间，有因有缘世间灭。秦采薇与迦那罗终究还是未能逃出那个“情”字，种下了因，食下了果，此间滋味也只有他们自己可知。]],["title"]=[[尘缘往事叁]],["type"]=2,["type2"]=1},["20032"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20032,["open"]=1,["text"]=[[听闻有位男性幽冥教徒因在少林寺内迷路，由于太饿了而扮作妇女偷馒头被擒。还好当时在场的没有其他幽冥教徒，不然此事一出这位教徒估计再无脸面继续在幽冥教混了。少侠往后行走江湖可务必带好干粮，若是迷路也多找人问问，可别向这位教徒一样出此下策。]],["title"]=[[迷路的幽冥教徒]],["type"]=2,["type2"]=1},["20033"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20033,["open"]=1,["text"]=[[黄河老祖祖醉翁素来只好两物，一是酒，一是酒杯。祖醉翁自己藏有一堆好酒，还时常拿着酒杯到黄河河套处向过路人讨酒喝，也不知有多少人被他骗了去。]],["title"]=[[嗜酒如命祖醉翁]],["type"]=2,["type2"]=1},["20034"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20034,["open"]=1,["text"]=[[桃庄有一少年虽出生乡野却有极佳的作画天赋，未曾学过画却能将名家画作临摹得七八分，真是英雄出少年啊。]],["title"]=[[少年英才]],["type"]=2,["type2"]=1},["20035"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20035,["open"]=1,["text"]=[[前些日子有一捕快失踪了，听闻他是在追查独臂李途中失踪的。独臂李此人能驱使老鼠，为人阴险狠毒，那捕快多半是凶多吉少了。只是可怜他那结发妻子刚诞下一子，既要担起家里生计还有照顾幼子和重病母亲，往后的日子不知要如何艰苦了。]],["title"]=[[失踪的捕快]],["type"]=2,["type2"]=1},["20036"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20036,["open"]=1,["text"]=[[听闻方敬渊静坐思过时偷喝酒被莫天雄发现，多加了几天静坐，而李纯罡又在筹划给他送酒。如此循环下去，也不知方敬渊会不会要静坐到天荒地老，李纯罡这贴心的小师弟到底想不想让他师兄出来。]],["title"]=[[贪酒的大师兄]],["type"]=2,["type2"]=1},["20037"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20037,["open"]=1,["text"]=[[终南山的掌药道长不知是不是因为常年与药材打交道的缘故，他制作龟苓膏的技艺真是一绝，尝过的人都说好。]],["title"]=[[终南山的龟苓膏]],["type"]=2,["type2"]=1},["20038"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20038,["open"]=1,["text"]=[[那些名门弟子也不知是为何，记性健忘老丢东西，不是丢礼盒就是丢簪子，还有丢佩剑的，常常托人帮他们寻找。听闻最近有门派长老针对此事研发出了药膳，有望增强弟子们的记性。]],["title"]=[[健忘的弟子们]],["type"]=2,["type2"]=1},["20039"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20039,["open"]=1,["text"]=[[听闻温子初心善，但心善太过，常在山路上偷偷地把猎户猎的鹿放了，在下认为迟早有一天他会被猎户揍一顿。]],["title"]=[[善人义士温子初]],["type"]=2,["type2"]=1},["20040"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20040,["open"]=1,["text"]=[[齐伯庸对洛还君真是一往情深，希望他终有一日会守得花开见月明。]],["title"]=[[有情终成眷属]],["type"]=2,["type2"]=1},["20041"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20041,["open"]=1,["text"]=[[谢宫天嘴笨时常惹秦芸生气，秦芸不舍得对谢宫天下毒便对其他万灵弟子下毒，再叫中毒弟子去找谢宫天解毒，她知道谢宫天心善，会因愧疚来找自己道歉。现已有多名弟子为他们的感情献身了，据说有些弟子因无法忍受，开始教谢宫天话术。]],["title"]=[[欢喜冤家]],["type"]=2,["type2"]=1},["20042"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20042,["open"]=1,["text"]=[[丁红蝶向来说一不二，不许他人碰的东西，即使是她死了也还是不许碰。]],["title"]=[[说一不二丁红蝶]],["type"]=2,["type2"]=1},["20043"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20043,["open"]=1,["text"]=[[万灵谷附近村子，有一民居后院的柿子树结的柿子香甜爽滑，十分好吃。只是得早些去，晚了连叶子都不剩。]],["title"]=[[后院的柿子]],["type"]=2,["type2"]=1},["20044"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20044,["open"]=1,["text"]=[[据传侠士慕衣白的隐居之处被人查出，在下认为这是迟早的事。他想离开江湖与妻子偕老白头，就此隐居不问世俗，但是他放下了江湖，江湖又岂会放过他。江湖中常有人与他一般，又有多少人能得偿所愿？人一日在江湖，一生都在江湖。]],["title"]=[[离不开的江湖]],["type"]=2,["type2"]=1},["20045"]={["arg1"]=[[fb35]],["arg2"]=0,["arg3"]=0,["con1"]=1,["con2"]=0,["con3"]=0,["id"]=20045,["open"]=1,["text"]=[[听闻虚渺宫的大师姐武功高强与世无争，对东洋之事甚是了解，常说些例如“阿宅”、“动漫”这般令人费解之词，但据说她从未去过东洋，也未见有东洋的好友，真是奇也怪也。]],["title"]=[[奇怪的大师姐]],["type"]=2,["type2"]=1},["20046"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20046,["open"]=1,["text"]=[[听闻贺长干昔年为叶妄生所救，自此便一路跟随叶妄生入了幽冥教，成为如今的幽冥教护法。]],["title"]=[[贺长干往事]],["type"]=2,["type2"]=1},["20047"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20047,["open"]=1,["text"]=[[据闻毒无常的师傅对他时好时坏，他喜怒无常的性子大概也是由此而来。]],["title"]=[[毒无常往事]],["type"]=2,["type2"]=1},["20048"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20048,["open"]=1,["text"]=[[传闻江湖上曾有一名用剑高手，佩剑名为流觞，剑招奇异多变，江湖众多高手败于剑下，一时间这用剑高手风头大盛。月有阴晴圆缺，人有旦夕祸福，某日用剑高手被他的仇人们围困。一场激战过后，用剑高手虽拼死杀出但也武功尽废，就此在江湖上消声遗迹。江湖上从不缺高手，不消两年他的名字便再无人谈及，偶有人提起，也只记得他大概是姓李罢。]],["title"]=[[被遗忘的高手]],["type"]=2,["type2"]=1},["20049"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20049,["open"]=1,["text"]=[[华山村的收成向来不好，村民们一直过着勉强度日的生活，而杂货铺的谢老板却不甘就此认命。为了让妻儿过上好日子，谢老板一直四处奔波做生意，日子渐渐的好了起来，但谢老板却几乎是每日都不着家，就连逢年过节谢老板也时常在外奔波。妻子患病，身体每况愈下，但谢老板忙于生意，对妻子疏于关心，并不知情。某年除夕夜，谢老板还在赶回家的路上，而妻子却在别家的欢声笑语中咽了气，手里还攥着大婚时谢老板送她的玉簪子。]],["title"]=[[杂货铺往事]],["type"]=2,["type2"]=1},["20050"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20050,["open"]=1,["text"]=[[传闻曾有一位商界贵人十分宠爱自己的小妾，但其妻善妒，而贵人惧内，于是贵人将小妾养于别院。过了几年，小妾成功诞下一个女婴，也就在此时，小妾的存在被正妻发现。正妻派出杀手欲将小妾和女婴赶尽杀绝，而贵人却畏畏缩缩不敢出手相助。小妾恨自己识人不清，可世间也无后悔药。为保女婴性命，小妾替她取名洛还君，将她弃于落月山庄门口后，怀抱着假婴跳崖自尽。]],["title"]=[[茶馆奇闻壹]],["type"]=2,["type2"]=1},["20051"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20051,["open"]=1,["text"]=[[传闻洛还君实乃落月山庄庄主的私生女，因顾及名声不便相认，然又不舍送出，便认作义女养在身边。]],["title"]=[[茶馆奇闻贰]],["type"]=2,["type2"]=1},["20052"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20052,["open"]=1,["text"]=[[传闻杀人神医平老怪的师傅也是位医术高超的神医，可惜不过而立之年便英年早逝。平老怪深受打击，认为正是师傅救人无数，惹了鬼差才会招此灾祸。自此平老怪便立下救一人，杀一人的规矩。]],["title"]=[[茶馆奇闻叁]],["type"]=2,["type2"]=1},["20053"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20053,["open"]=1,["text"]=[[据传杀人神医平老怪师承于一个神秘门派，此门派的创始人医毒双绝，也曾修道，很是重视阴阳调和。他认为只救人是在破坏阴阳，只有同时杀一人才可维持阴阳平衡。故此他便立下“救一人，杀一人”的门规，门派弟子若不遵循便视为叛离师门，将受到全师门的追杀。]],["title"]=[[茶馆奇闻肆]],["type"]=2,["type2"]=1},["20054"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20054,["open"]=1,["text"]=[[听闻金甲六仙，虽都已是花甲之年，武功高强，但依然如孩童一般天真，像桃花一样烂漫。]],["title"]=[[金甲六仙]],["type"]=2,["type2"]=1},["20055"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20055,["open"]=1,["text"]=[[金甲六仙走入江湖已然几十年，归来依然如孩童，此般心性在江湖之上也怕是无人能及。]],["title"]=[[难以企及的心性]],["type"]=2,["type2"]=1},["20056"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20056,["open"]=1,["text"]=[[传闻辛友青屡次上京赶考皆遗憾落榜，寻常人受此打击都要萎靡不振一段时日，但辛友清向来看得开，落榜后便回到扬州在十里街支个摊子卖书贩画，同时再准备下次的进京赶考，倒也有几分采菊东篱下的悠然之意。]],["title"]=[[悠然自得辛友清]],["type"]=2,["type2"]=1},["20057"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20057,["open"]=1,["text"]=[[传闻赌仙走遍各大赌场为能寻到能与他一赌之人，郁郁寡欢之下得了一场大病。大夫告诉他这是心病还得心药医，于是病情稍好赌仙便起身游历，誓要寻到能与他一高下之人。]],["title"]=[[难求一败]],["type"]=2,["type2"]=1},["20058"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20058,["open"]=1,["text"]=[[赌仙赌术超绝，赢得的金银财宝数不胜数。但据传他对那些金银珍宝素来不喜，唯爱收集品级上乘的雨花石。他道雨花石乃天赐珍宝，凝聚了天地之灵气，孕有万物之风采，每一颗皆是世上独一。]],["title"]=[[赌仙之好]],["type"]=2,["type2"]=1},["20059"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20059,["open"]=1,["text"]=[[少侠行走江湖时，若是感到寂寞寒冷可去襄阳城的觅香楼买一壶即墨老酒，对月而饮，暖暖身心。]],["title"]=[[即墨老酒]],["type"]=2,["type2"]=1},["20060"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20060,["open"]=1,["text"]=[[听闻江耀祖一案已被成功翻案，陷害江大人的奸臣小人尽数被捕，江大人一家终是沉冤得雪。但人死不能复生，只可惜江家满门忠烈，只余下江孟双一人。]],["title"]=[[沉冤得雪]],["type"]=2,["type2"]=1},["20061"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20061,["open"]=1,["text"]=[[据传十五年前王心研的师傅因父辈恩怨与白发老翁结下仇怨，在一次争斗中被白发老翁所杀，当时王心研躲在角落目睹了一切。当白发老翁想要斩草除根时，王心研躲起来逃过一劫。从此她便独自一人在江湖飘荡，在十五年后终又在苏州遇到了白发老翁。看着他和徒弟其乐融融，王心研不禁想起自己早逝的师傅，顿时怨起，趁着白发老翁不备将其击杀。大仇得报，但此怨未了。当李永福找来时，王心研想起了自己的徒儿，便知此怨怕是无所了。]],["title"]=[[冤冤相报无所了]],["type"]=2,["type2"]=1},["20062"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20062,["open"]=1,["text"]=[[听闻李永福幼时遇上天灾，一家四口便想逃难到富庶的江南寻个活路，却未曾想一路坎坷，到达时只余李永福一人。眼看李永福也要饿死之际他遇到白发老翁，白发老翁收他为徒，待他如亲儿。李永福认真学武，希望以后能找个好差事，能让白发老翁颐养天年。但世事难料，他们行至苏州，李永福不过离开买酒的功夫，便与恩师天人永隔。]],["title"]=[[师恩未得报]],["type"]=2,["type2"]=1},["20063"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20063,["open"]=1,["text"]=[[传闻黄员外常年流连于花柳之地，经年累月下来身体虚空，得了一场大病后卧床不起。他四处求医问药皆不好转，直到某天他遇到了一位游方道士。道士交予他一个偏方，是以人骨作药引，能补上他亏空的气血。黄员外未有挣扎，立刻花重金寻来盗墓贼替他取人骨。偏方果真管用，他的身体日渐恢复。江山易改，本性难移，痊愈的黄员外立马就跑去寻花问柳。黄员外即害怕重病卧床，又舍不得温香软玉，于是便长期与盗墓贼保持合作，甚至将药引改为药膳，以人骨熬汤，日夜服之。]],["title"]=[[当世食尸鬼]],["type"]=2,["type2"]=1},["20064"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20064,["open"]=1,["text"]=[[江湖传闻无名剑客的妻子李纷纷，曾是万灵谷长老巫水镜之徒，后弑师叛逃，被万灵谷下令追杀，至今下落不明。]],["title"]=[[李纷纷的身份]],["type"]=2,["type2"]=1},["20065"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20065,["open"]=1,["text"]=[[华山大师兄方敬渊嗜酒如命，多次被关在后山面壁思过，这回不知道哪位侠士会受他师弟李纯罡之托，给他送陈年汾酒去。]],["title"]=[[李纯罡的请求]],["type"]=2,["type2"]=1},["20066"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20066,["open"]=1,["text"]=[[听说襄阳城出了一位叫陈连生的大才子，屡次上献奇计击退金兵，昔年他不顾身体孱弱，更不顾妻子和母亲的反对，决意要弃文从武，上战场杀敌，还好得一位少侠点醒，选了合适的路子报效国家。后来有抱负而不得之人知晓了此事经过，纷纷有所感悟。]],["title"]=[[陈连生报国之行]],["type"]=2,["type2"]=1},["20067"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20067,["open"]=1,["text"]=[[有消息称，屠杀逍遥林附近村民的强盗，实际为红花会的人假扮，那红花会暗地早与柳玄风勾结，应是受柳玄风之命，至于目的为何，也许跟周天功的线索有关。]],["title"]=[[逍遥林村民之死]],["type"]=2,["type2"]=1},["20068"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20068,["open"]=1,["text"]=[[传闻青老太四兄妹都是武当弟子，当初下山盗走柳玄风故居宝物之事似乎受人指使。]],["title"]=[[青老太四兄妹]],["type"]=2,["type2"]=1},["20069"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20069,["open"]=1,["text"]=[[多年前，有位算命先生路经一处村庄，向村民讨碗水喝，得到村民们的热情招待，算命先生趁着歇脚的工夫，为其中几位村民算卦解灾，所言所测皆如神算，离去前，又见一男童相貌不俗，忍不住为其算卜了一卦，哪知此男童竟命犯天煞，注定无老伴终,孤独一生，而这男童正是年幼时的韩一枫。]],["title"]=[[韩一枫的命卦]],["type"]=2,["type2"]=1},["20070"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20070,["open"]=1,["text"]=[[江湖上极少有人知晓，柳玄风曾是崆峒派的弟子，与有“落日神拳”之称的王绝关系甚好。]],["title"]=[[柳玄风曾经的身份]],["type"]=2,["type2"]=1},["20071"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20071,["open"]=1,["text"]=[[江湖传闻在落英谷叫小飞的男孩，是前朝萧王的后裔，一直被朝廷某位大人物下令追杀。]],["title"]=[[落英谷小飞]],["type"]=2,["type2"]=1},["20072"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20072,["open"]=1,["text"]=[[华山的掌门夫人丁香华，虽从未习武，却有一手好厨艺，若江湖举办厨艺大赛，只要这位出手，必榜上有名。]],["title"]=[[华山丁香华]],["type"]=2,["type2"]=1},["20073"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20073,["open"]=1,["text"]=[[江湖众人皆知峨眉派派规森严，凡弟子因红尘误事必受重罚。自传出狄水清是为一男子背叛峨眉，令峨眉派颜面尽失，据说往后误入情网的峨眉弟子，要一律废除武功逐出门派，以正峨眉之风。]],["title"]=[[峨眉派的传闻]],["type"]=2,["type2"]=1},["20074"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20074,["open"]=1,["text"]=[[二十五年前玄灵师太单人单剑斩尽荆南九煞，一战成名，江湖上无人不慕其风采。但也那一年，玄灵师太被伪装成受害人的盗匪欺骗，误认为一位侠义之士霸凌弱小、残害他人，不容侠士分辩，将其刺死，后来得知真相，原来是一伙盗匪屠杀百姓在先，反被侠士所灭，其余侥幸活下来的盗匪却心有不甘，听闻玄灵师太嫉恶如仇，故颠倒黑白，设下此计。而玄灵师太错害好人，内心悔恨不已，杀死那欺瞒她的盗匪后，自此将随身佩剑清风存于紫金庵，足足十年不曾用剑。]],["title"]=[[玄灵师太的悔恨]],["type"]=2,["type2"]=1},["20075"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20075,["open"]=1,["text"]=[[执掌峨眉下院的静庭师太，江湖上只知她出自官绅之家，家学渊源，却不知晓她中年出家的缘由。传闻静庭师太自小习读佛经，恪守礼节，豆蔻年华与父亲好友之子定亲，谁料未婚夫奉旨进山剿匪，却从此下落不明，而静庭师太拒绝退亲改嫁，一等数年，直到确认未婚夫的死讯，才拜入峨眉，了却红尘。]],["title"]=[[静庭师太的红尘往事]],["type"]=2,["type2"]=1},["20076"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20076,["open"]=1,["text"]=[[有小道消息称，峨眉掌门宝相神尼不喜长得漂亮的女弟子，那种五大三粗相貌平平的才入她的眼。]],["title"]=[[峨眉掌门的喜好]],["type"]=2,["type2"]=1},["20077"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20077,["open"]=1,["text"]=[[当年玄悲大师曾留下遗愿，希望能找回少林遗失的”韦陀杵”秘籍，传闻偷盗之人正是”周天功”的修炼者，而如今少林藏经阁诸多秘籍被盗，又和周天功有关，当真是孽缘啊。]],["title"]=[[少林玄悲大师的遗愿]],["type"]=2,["type2"]=1},["20078"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20078,["open"]=1,["text"]=[[江湖传闻，妙真带回少林寺的一孩童，手中有抄写的周天功秘籍，虽然少林寺多次否认，但还是有不少人准备潜入少林一探究竟。]],["title"]=[[少林风起]],["type"]=2,["type2"]=1},["20079"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20079,["open"]=1,["text"]=[[“峨眉三剑”行侠仗义，江湖上名声远扬。大师姐白剑枫，是最受峨眉掌门看中的年轻弟子，年龄虽是三位中最小的，但无论武功心性皆是上乘。二师姐花剑岚，武功功底薄弱，不过品性天真浪漫，有一颗稚子之心。老三莫剑秋，师承玄灵师太，痴迷剑术，心无旁骛，也因此不通俗务。]],["title"]=[[峨眉三剑]],["type"]=2,["type2"]=1},["20080"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20080,["open"]=1,["text"]=[[也不知何时起，侠客们极爱和少林寺的扫地僧比武，现在少林寺的弟子没一身真本领都不敢去扫地了。]],["title"]=[[少林扫地僧]],["type"]=2,["type2"]=1},["20081"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20081,["open"]=1,["text"]=[[在华山的落雁峰有位归隐的无名老者，仪容气度宛若仙人，有传闻说他是几十年前威震江湖的风前辈，如今的他时常雕刻木雕，将精湛的剑法融入其中，若有人观赏木雕得以领悟剑意，简直胜过十年苦练。]],["title"]=[[华山无名老者]],["type"]=2,["type2"]=1},["20082"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20082,["open"]=1,["text"]=[[华山之巅，此沐浴清风回云之处，立有一座石碑，祭于侠者金氏，留有诗曰：飞雪连天射白鹿，笑书神侠倚碧鸳。]],["title"]=[[华山之巅石碑]],["type"]=2,["type2"]=1},["20083"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20083,["open"]=1,["text"]=[[武林盟为让江湖武学减少失传，特意设先贤书案，有能之士只要通过圆通大师所说的考验，即可在书案上留下武学，待有缘人继承。]],["title"]=[[先贤书案]],["type"]=2,["type2"]=1},["20084"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20084,["open"]=1,["text"]=[[幽冥教主常年身披一件黑色长袍，口鼻亦有黑纱遮掩，少有人见过他的真面目，传言幽冥教主是位女子，年龄不详，且有磨镜之好。嘘，这消息少侠切勿乱传，小心祸从口出。]],["title"]=[[幽冥教主的秘密]],["type"]=2,["type2"]=1},["20085"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20085,["open"]=1,["text"]=[[说起如今江湖最出名的铸剑师，分别为西绝华山沐清风、南隐唐门唐阡陌、北水之巅轩辕生以及超然于世的欧冶子。]],["title"]=[[四大铸剑师]],["type"]=2,["type2"]=1},["20086"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20086,["open"]=1,["text"]=[[据传汝州城的山贼岳熊，与王员外之女王芙是青梅竹马，两人曾定过亲事，后来岳熊被朝中权贵逼得落草成寇，此生心愿除了报仇便是娶王芙为妻，哪知王芙移情别恋，岳熊前去抢亲落个死不瞑目的下场，昔年好汉得此终局怎不叫人唏嘘。]],["title"]=[[岳熊之悲]],["type"]=2,["type2"]=1},["20087"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20087,["open"]=1,["text"]=[[丐帮的老帮主施楠虽武功高强，但心机谋略不足，轻易便遭人欺骗算计，被关押在一个隐秘的地方不得自由，嘿嘿，至于其中详情在下也不知晓。]],["title"]=[[施楠下落]],["type"]=2,["type2"]=1},["20088"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20088,["open"]=1,["text"]=[[二十年前，苏念双与武当弟子裴舒云在桃园共埋下一坛女儿红，两人约定大婚之日开坛，后来裴舒云下山历练，遇一邪医作恶，他出手诛灭邪医，却不慎身中对方研制的剧毒，甚至来不及见苏念双最后一面便闭目而逝，这女儿红也因此二十年不见天光。]],["title"]=[[苦酒酿情悲韶华]],["type"]=2,["type2"]=1},["20089"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20089,["open"]=1,["text"]=[[那些闯江湖的侠客，凡自认有几分本事的人，都会上武功镇的崇武楼闯一闯。在下听说只要能打赢守门的层主，可以获得不少好处。]],["title"]=[[崇武楼的试炼]],["type"]=2,["type2"]=1},["20090"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20090,["open"]=1,["text"]=[[江湖上关于谁杀死柳玄风父母一事众说纷纭，在下斗胆猜测，幕后凶手乃崆峒派里德高望重的大人物。少侠可听说过章作之？此人豪气云天，颇有侠名，在他成为天启帮的弟子之前，曾是被人精心训练出来的杀手，他身上既有柳玄风亡母的玉佩，武功又为崆峒派的绝学，这些线索不得不让在下多想。]],["title"]=[[江湖谜案]],["type"]=2,["type2"]=1},["20091"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20091,["open"]=1,["text"]=[[少侠可有听说过白辰山庄？当年它被大火烧毁，江湖上无数人还为此伤感，却少有人知晓这山庄是永夜楼暗中培养的分舵，表面正派，实则残害了多少武林之人，后来因卷入永夜楼楼主之争被灭，据说白辰山庄的少庄主并没有死于那场大火，而是逃往了天竞门，成为五脉门主之一。]],["title"]=[[白辰山庄秘闻]],["type"]=2,["type2"]=1},["20092"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20092,["open"]=1,["text"]=[[这江湖啊就像一潭看不见底的深水，表面巨浪滔天，水底更是暗流汹涌，少侠身处这水中，多知晓点消息准是好事。话说鸩羽山庄自上一代庄主建立“七杀堂”，如今由欧阳异德掌管，这七杀堂专搜罗幼童进行残酷训练，日后再命他们潜伏各大门派之中。和少侠有些交情的蜃，便是七杀堂派入永夜楼的细作。]],["title"]=[[七杀堂势力]],["type"]=2,["type2"]=1},["20093"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20093,["open"]=1,["text"]=[[武林中向在下打听永夜楼楼主身份的人多如繁星，可惜啊，楼主“永夜”在江湖上有千面之称，关于“永夜”真实面目在下也不知晓，不过，在下听说海鲸帮的余志枭曾为报“永夜”救命之恩，甘愿拜入永夜楼受其驱使，少侠只要顺着余志枭这条线索追查下去，说不定能有所收获。]],["title"]=[[永夜楼楼主]],["type"]=2,["type2"]=1},["20094"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20094,["open"]=1,["text"]=[[天竞门的笑笑子，本名公孙戚，极擅剑舞，每上梨园演一出，往往艺惊四座。不过这人脾气古怪，还立下了“三不舞”的规矩：权贵不舞、骚客不舞、无金银者不舞。凡破坏他规矩的人，嘿嘿嘿，那是一个比一个死的惨呐。]],["title"]=[[笑笑子的三不舞]],["type"]=2,["type2"]=1},["20095"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20095,["open"]=1,["text"]=[[烟雨楼的姑娘各个色艺双全，老鸨花四娘更不简单，少侠不如猜猜她的真实身份？好好好，在下也不卖关子了，如今的花四娘正是永夜楼安插好的棋子，至于目的为何，少侠往嘉兴镇走上一趟，也许能知晓一二。]],["title"]=[[烟雨楼的老鸨]],["type"]=2,["type2"]=1},["20096"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20096,["open"]=1,["text"]=[[空道人，原名柳在溪，以卦术游走江湖，有“神卦”之称。当年天竞门掌门百花杀对他十分欣赏，邀他入天竞门被拒后，于是与他以卜卦三试打赌。百花杀用计巧胜，怕空道人生气，又承诺她死后空道人可随意去留，暗示对方想要离开天竞门，大可将她杀死，不过空道人见对方求贤若渴，早对天竞门心向往之，这场赌约，亦成一桩美谈。]],["title"]=[[空道人的赌约]],["type"]=2,["type2"]=1},["20097"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20097,["open"]=1,["text"]=[[虎威山的大当家韩虎，赫赫有名的贼人，仗着武功高强肆意作恶，有关他的武功来历，江湖上众说纷纭，更有甚者猜测他和嵩山宗的叛徒韩一枫为父子关系，不过依在下所见，这消息并不可靠，但二人之间必然存在某种联系。]],["title"]=[[虎威山韩虎来历]],["type"]=2,["type2"]=1},["20098"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20098,["open"]=1,["text"]=[[少林寺的觉因，因家中变故剃度出家，但尘缘未了，与青梅江映蓉彼此有情，却又互相不曾表明，幸而有好心的少侠帮忙，用一根玉簪促成了这段良缘，令世间少了一桩憾事。]],["title"]=[[红尘玉簪情]],["type"]=2,["type2"]=1},["20099"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20099,["open"]=1,["text"]=[[武林盛传“周天得、天下得”，至于这周天功具体有何神奇之处，江湖说法不一，有称它是当世第一武学秘籍，习之能成绝世高手；也有说修炼其内功可令人返老还童；甚至关外还流传秘籍里藏有能颠覆王朝的秘密。可惜柳玄风一死，线索也随之断绝。]],["title"]=[[周天功秘辛]],["type"]=2,["type2"]=1},["20100"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20100,["open"]=1,["text"]=[[被任天南给予厚望的段潇，偏爱游戏红尘，有负其习武天资，然而儿时他也有练就一身功夫行侠仗义的梦想，只因错救恶人，害同门弟子惨死，后来恶人又成匪盗，再害无辜之人，自此段潇困于内疚的情绪之中，对江湖心生厌倦，用醉生梦死图个清闲自在。]],["title"]=[[风流公子伤心事]],["type"]=2,["type2"]=1},["20101"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20101,["open"]=1,["text"]=[[最近官府严查一种江湖邪术，传闻此术能操作人的梦境，让人陷美梦之中，随之越来越难以清醒，最终成为傀儡，即便是武功高强者也不例外。]],["title"]=[[入梦傀儡术]],["type"]=2,["type2"]=1},["20102"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20102,["open"]=1,["text"]=[[据天都峰弟子所言，天都峰上白牡丹姐姐虽然看起来弱不禁风，但其实背地里是个武道高手。别看她平日里不出手，要是有人想打她的注意，她一人打五六个武夫也是不在话下。]],["title"]=[[白牡丹趣闻]],["type"]=2,["type2"]=1},["20103"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20103,["open"]=1,["text"]=[[据峨眉挑夫所说，峨眉派的女侠们对峨眉山茶情有独钟，可萧梦莹女侠喜欢的却是蜀中唐门一带所出的茶叶，或许个人口味不同吧。]],["title"]=[[女侠喜茶]],["type"]=2,["type2"]=1},["20104"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20104,["open"]=1,["text"]=[[也许是受了坊间话本的影响，近来西岳华山一带兴起一阵赠送恋人金丝雀的热潮，一时间华山树木惨遭拍击，损失惨重。华山掌门莫天雄日前对此等行为发表了严厉谴责。]],["title"]=[[金丝雀之灾]],["type"]=2,["type2"]=1},["20105"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20105,["open"]=1,["text"]=[[你吃过最独特的食材是什么？雪山鹰鹫？藏边蜈蚣？还是辟毒怪蛙？某个纵横食界数十年的老饕餮曾说过，自己一生人间尝尽珍馐，也吃过千奇百怪的食材，独独没吃过深潭白鱼。]],["title"]=[[独特的食材]],["type"]=2,["type2"]=1},["20106"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20106,["open"]=1,["text"]=[[据传，少林铜人巷内有十八铜人，武艺高强，少林弟子须过得铜人巷一关，方可下山行走江湖。不过，有部分在少林游历过的侠士感觉铜人数量偏少，对十八铜人这个说法表示怀疑。]],["title"]=[[少林铜人]],["type"]=2,["type2"]=1},["20107"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20107,["open"]=1,["text"]=[[行走江湖难免深入山林的时候，方向感不强的侠士往往会迷失方向。迷路之时，不妨先观察差异，再行决定方向。有时，仔细地观察，冷静地决断，往往能让侠士们少走很多冤枉路。]],["title"]=[[密林寻路]],["type"]=2,["type2"]=1},["20108"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20108,["open"]=1,["text"]=[[相传，于中原土地之上耸立着一座神秘大山，其高可入云。根据周边的山民或曾进过大山的人讲述，此山之中藏有诸多秘密。凡进入之人都会被山中精怪迷惑，并将其蚕食。故此，很多人对此山敬而远之，不敢靠近。]],["title"]=[[迷山异闻壹]],["type"]=2,["type2"]=1},["20109"]={["arg1"]=20108,["arg2"]=0,["arg3"]=0,["con1"]=4,["con2"]=0,["con3"]=0,["id"]=20109,["open"]=1,["text"]=[[多年前，一位樵夫误入迷山，从此杳无音讯。当人们在怒江下游发现此人时，樵夫已经遍体鳞伤，不省人事。樵夫醒来后，众人不解便询问原由，可樵夫则目光呆滞，满脸惊恐，就好像见到什么极其可怕之物。]],["title"]=[[迷山异闻贰]],["type"]=2,["type2"]=1},["20110"]={["arg1"]=20109,["arg2"]=0,["arg3"]=0,["con1"]=4,["con2"]=0,["con3"]=0,["id"]=20110,["open"]=1,["text"]=[[据逃出迷山的樵夫说，他是因为贪图迷山中的珍稀木料这才冒险进入。进入迷山后没走多久便发生了诡异的现象，山中渐渐浓雾弥漫，而且越接近山顶浓雾中忽隐忽现的诡异身影越多。最后樵夫慌不择路逃进一片荆棘林中，就在他慌神之时，转眼看见一个金毛蓝眼的怪物站在不远处盯着他。樵夫被此景吓得双腿发软，跳崖而逃，这才顺着水流飘到怒江下游被人们发现。]],["title"]=[[迷山异闻叁]],["type"]=2,["type2"]=1},["20111"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20111,["open"]=1,["text"]=[[传闻，武林初成之时，伴随着一起兴起的还有一个特别的组织。它不同于其他门派势力，并没有创宗立派，而是在当时最为繁荣的城池修建一所庞大的客栈，天下客栈从这开始便存在于江湖之中，它不同于其他客栈，关于它背后庞大的秘密，则无人知晓。]],["title"]=[[天下客栈壹]],["type"]=2,["type2"]=1},["20112"]={["arg1"]=20111,["arg2"]=0,["arg3"]=0,["con1"]=4,["con2"]=0,["con3"]=0,["id"]=20112,["open"]=1,["text"]=[[武林之中，关于天下客栈的实力以及它幕后的主导者，几乎所有传出的信息全都模糊不清。但天下客栈的三大规定却是所有武林人士知晓且不敢玩愚的。]],["title"]=[[天下客栈贰]],["type"]=2,["type2"]=1},["20113"]={["arg1"]=20112,["arg2"]=0,["arg3"]=0,["con1"]=4,["con2"]=0,["con3"]=0,["id"]=20113,["open"]=1,["text"]=[[重光势力日益猖獗，天都峰脚下一间客栈拔地而起，写有“天下客栈”字样的牌匾尽显威严。有关于天下客栈的信息仅流传于一些江湖资历较老的前辈之中，相传，天下客栈不属于任何一方势力，它的权力和势力却凌驾于任何一方乃至朝廷之上。关于天下客栈的由来以及它背后的信息近乎无人知晓，但可以确定的是，每当天下客栈出现在江湖之中，那就预示着即将会有一次大的变故发生。]],["title"]=[[天下客栈叁]],["type"]=2,["type2"]=1},["20114"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20114,["open"]=1,["text"]=[[自天下客栈成立以来，客栈掌柜便立下了三条明文规定：第一，凡是天下客栈内，所有人无论势力、官职、权贵，全部平等。第二，店内不可相互争斗，无论原由，凡违反者即刻清出店内，从此天下客栈不再与此人来往，如有不从或执意与天下客栈对立者，天下客栈便会出手将此人从江湖中除名。第三，天下客栈内不可行欺诈、逼迫、威逼利诱等手段，一经发现，双方均会受到同等惩罚，无论原由。]],["title"]=[[天下客栈的规定]],["type"]=2,["type2"]=1},["20115"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20115,["open"]=1,["text"]=[[传闻称前任昆仑大师兄抵不住诱惑误入邪道，习得邪法后不断提升实力，欲要危害武林。而后在平安小镇中被一神秘高手诛杀，听说死状极其惨烈，头被锤的血肉模糊，而现场只留有一柄硕大的铁锤，锤面上浮雕雕刻了一个大大的“张”字，格外显眼，不知是何人替天行道，除此大患。]],["title"]=[[正义执行]],["type"]=2,["type2"]=1},["20116"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20116,["open"]=1,["text"]=[[中原武林存在一个势力，他们自称重光教，至于来历无人知晓，只听闻似乎是从关外而来。据江湖传言，他们似乎也是为了周天功而来，而且这些家伙实力不俗，已经和多个门派产生冲突。]],["title"]=[[重光其壹]],["type"]=2,["type2"]=1},["20117"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20117,["open"]=1,["text"]=[[近日，天竞门内来了一些陌生的面孔，他们年龄不一，男女同行，唯一相同的是这些人全都背着用绸缎包裹的古琴。自从这些人来以后，天竞门内的弟子会时不时听到悠扬的古琴之音，但这些琴曲却是从未听过的。]],["title"]=[[特殊访客]],["type"]=2,["type2"]=1},["20118"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20118,["open"]=1,["text"]=[[自从天竞门内来了些从未见过的乐师后，天竞门的弟子经常聚在一起谈论，说时常听到这些人弹奏的琴声，有时曲子悠扬婉转，听后让人顿感舒心，但又有时能听到琴曲激昂澎湃，让人内心愤怒不已。]],["title"]=[[琴曲动神]],["type"]=2,["type2"]=1},["20119"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20119,["open"]=1,["text"]=[[问情宫与全真两派渊源颇深，相传两派创派祖师交情极好，时常交流武学，因此两派武功之中既有相似之处，又有互相克制的地方。至于坊间流传的感情纠葛、始乱终弃，都是好事者凭空捏造的故事，侠士们可不要在两派弟子前提起，切记切记。]],["title"]=[[问情全真]],["type"]=2,["type2"]=1},["20120"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20120,["open"]=1,["text"]=[[重光教内，有一位被江湖中人戏称的混世魔王，虽说此人年纪不大，但她却是重光教内的重要成员，只不过重光的种种做法让人不禁为此女感到担忧。]],["title"]=[[神使宋青秋]],["type"]=2,["type2"]=1},["20121"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20121,["open"]=1,["text"]=[[相传数十年前，边境突然崛起一伙恶匪，在边境的村镇烧杀抢掠，无恶不作。那群恶匪来路不明，武功不弱，驻守官兵曾与他们多次交手，皆不敌惨败。屡次取胜的恶匪士气暴涨，更加肆意妄为。
忽有一日，边境的村落来了一名神秘的剑客，听闻村民所苦，未曾言语，只向村民索要了一壶酒便孤身前往匪寨。一夜之后，被恶匪掠去的女子悉数逃回。
据说那名剑客，一人一剑一壶酒，不消片刻便将恶匪尽数诛杀。待驻守官兵前去查看时，偌大的匪寨仅剩满地的尸体和一幅制作精良的脸谱。]],["title"]=[[神秘剑客]],["type"]=2,["type2"]=1},["20122"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20122,["open"]=1,["text"]=[[有江湖传闻称，某个不知名剑客在平安小镇一处荒园中偶然拾到了一幅脸谱，脸谱内部竟刻有一套不知名的剑法。那剑客研习后，剑法超群，短短数日便挑战了数名高手，且大获全胜。若不是那剑客心高气傲，惹得杀身之祸，如今的江湖中定会有他威名。]],["title"]=[[面下玄机]],["type"]=2,["type2"]=1},["20123"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20123,["open"]=1,["text"]=[[在下从某些商队那得知，塞外有两国现今正是剑拔弩张之时，两国间战事不断，搅的塞外人心惶惶。不少流民落草为寇，使得一些流匪的势力壮大，主要商路上有不少商队遭劫，如今那些流匪还开始侵扰中原的边境。]],["title"]=[[塞外战乱]],["type"]=2,["type2"]=1},["20124"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20124,["open"]=1,["text"]=[[近日，许多商队都称西部情况反常，山贼强盗很少出现不说，一些胆大的商队冒险选择昔日劫匪盛行的商路行商竟也平安归来。一些好奇的江湖人士也曾前往，想要探明真相，但都无终而返。]],["title"]=[[西部异动]],["type"]=2,["type2"]=1},["20125"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20125,["open"]=1,["text"]=[[近日，很多昆仑派的弟子在传昆仑山附近出现了怪事，一是每到深夜都会有奇怪的声音传来，二是外出的弟子多半没了音讯。许多人猜测那些弟子的失踪恐怕和深夜出现的古怪声音有关，于是昆仑派便派出几名弟子前去探查。结果那几名弟子狼狈而归，身上遍布抓痕，询问之下他们都称自己见到了散发着黑气的恶鬼在山中游荡，身上的抓痕也都是恶鬼所伤。]],["title"]=[[昆仑“恶鬼”]],["type"]=2,["type2"]=1},["20126"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=20126,["open"]=1,["text"]=[[近来江湖中有一传言，说是有好登山的旅客在某个深山中误入了一个深谷，而谷中竟有一个庞大的古镇。那旅客觉得惊奇，在镇中游览，却发现这镇中的居民个个都身强力健，有的能扛起三尺宽的巨木而不费吹灰之力，有的能在嶙峋的山路上飞奔如履平地。旅客以为自己误入了什么山精野怪的居所，吓得昏了过去。待第二日清醒之时，他已然置身山下，不由得怀疑昨夜所见只是一场幻梦，但盖在他身上的兽皮却证明昨夜并非梦境。]],["title"]=[[深山古镇其一]],["type"]=2,["type2"]=1},["20127"]={["arg1"]=20126,["arg2"]=0,["arg3"]=0,["con1"]=4,["con2"]=0,["con3"]=0,["id"]=20127,["open"]=1,["text"]=[[那误入深山古镇的旅客，回到住所后便将那一夜奇遇告知了几位好友。但几位好友都不相信，一个说是那旅客登山迷了路，怕落了面子，便找人买了一张兽皮，编撰了个故事糊弄他们；一个说是深山多瘴气，旅客吸入瘴气生出了幻觉罢了，那张兽皮指不定是哪个路过柴夫见旅客晕在荒野给他盖上的。说来道去都无人相信旅客，但旅客又是那般斩钉截铁，于是几人相约一同前往探个究竟。但几人在山中转了又转，别说古镇，就连半块砖瓦都未曾见着。深山草木茂盛，树影遮天，薄瘴弥漫，他们欲向山林的更深处探寻，却总是兜兜转转后回到起点。几经折腾，几人身乏力竭，只能无功折返。在这之后，就连那曾误入古镇的旅客也不由得怀疑那场奇遇究竟是不是真实所见，又或许真是一场幻梦罢了。]],["title"]=[[深山古镇其二]],["type"]=2,["type2"]=1},["30000"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=30000,["open"]=1,["text"]=[[在金牛武馆把木材房的木头送礼给柴房管事，可以学习基本拳脚到100级。]],["title"]=[[基本拳脚学习壹]],["type"]=3,["type2"]=1},["30001"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=30001,["open"]=1,["text"]=[[翻动十次华山村石室的书架，可以获得掌法总谱，翻阅后可以学习基本拳脚至100级。]],["title"]=[[基本拳脚学习贰]],["type"]=3,["type2"]=1},["30002"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=30002,["open"]=1,["text"]=[[在逍遥林的练武场对着木人练习，可以学习基本拳脚至150级。]],["title"]=[[基本拳脚学习叁]],["type"]=3,["type2"]=1},["30003"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=30003,["open"]=1,["text"]=[[在峨眉山的坡道，观摩石壁可以学习基本拳脚到300级。]],["title"]=[[基本拳脚学习肆]],["type"]=3,["type2"]=1},["30004"]={["arg1"]=[[youxia]],["arg2"]=0,["arg3"]=0,["con1"]=5,["con2"]=0,["con3"]=0,["id"]=30004,["open"]=1,["text"]=[[在长安城的奎星楼，散人可以请教李崇虎基本拳脚至500级。]],["title"]=[[基本拳脚学习伍]],["type"]=3,["type2"]=1},["30005"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=30005,["open"]=1,["text"]=[[在金牛武馆把柴房的柴刀送给马房管事，然后去习武堂和王教头对话，再用木人练习可以学习基本剑法到100级。]],["title"]=[[基本剑法学习壹]],["type"]=3,["type2"]=1},["30006"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=30006,["open"]=1,["text"]=[[在京城西单，可以请教单云然基本剑法到500级。]],["title"]=[[基本剑法学习贰]],["type"]=3,["type2"]=1},["30007"]={["arg1"]=[[youxia]],["arg2"]=0,["arg3"]=0,["con1"]=5,["con2"]=0,["con3"]=0,["id"]=30007,["open"]=1,["text"]=[[在襄阳城的大校场，散人可以向剑术教头请教基本剑法到300级。]],["title"]=[[基本剑法学习叁]],["type"]=3,["type2"]=1},["30008"]={["arg1"]=[[youxia]],["arg2"]=0,["arg3"]=0,["con1"]=5,["con2"]=0,["con3"]=0,["id"]=30008,["open"]=1,["text"]=[[在长安城的北大街，散人可以请教齐云彪基本剑法至500级。]],["title"]=[[基本剑法学习肆]],["type"]=3,["type2"]=1},["30009"]={["arg1"]=0,["arg2"]=0,["arg3"]=0,["con1"]=0,["con2"]=0,["con3"]=0,["id"]=30009,["open"]=1,["text"]=[[在金牛武馆的柴房劈柴可以学习基本刀法到100级。]],["title"]=[[基本刀法学习壹]],["type"]=3,["type2"]=1},["30010"]={["arg1"]=0,["arg2"]=0,["a